CREATE TABLE vendas(id INTEGER, cliente TEXT, desconto REAL);
INSERT INTO vendas VALUES
  (1, 'Ana', 10), (2, 'Bia', NULL),
  (3, 'Caio', NULL), (4, 'Dani', 5);

SELECT COUNT(*)        AS linhas,           -- 4
       COUNT(desconto) AS com_desconto,     -- 2
       AVG(desconto)   AS media_so_preenchidos,  -- 7.5
       AVG(COALESCE(desconto, 0)) AS media_todas -- 3.75
FROM vendas;
